function solve(s, p) {
  const m = s.length;
  const n = p.length;
  let next = new Array(n + 1).fill(false);
  next[n] = true;

  // Match the empty string against each pattern suffix.
  for (let j = n - 1; j >= 0; j--) {
    if (j + 1 < n && p[j + 1] === '*') {
      next[j] = next[j + 2];
    }
  }

  for (let i = m - 1; i >= 0; i--) {
    const current = new Array(n + 1).fill(false);
    for (let j = n - 1; j >= 0; j--) {
      const matches = p[j] === '.' || p[j] === s[i];
      if (j + 1 < n && p[j + 1] === '*') {
        // Skip the atom, or consume a character and retain it.
        current[j] = current[j + 2] || (matches && next[j]);
      } else {
        current[j] = matches && next[j + 1];
      }
    }
    next = current;
  }

  return next[0];
}
```

