function solve(s) {
  const n = s.length;
  const cuts = Array.from({ length: n + 1 }, (_, i) => i - 1);

  for (let center = 0; center < n; center++) {
    // Odd-length palindromes.
    for (let left = center, right = center;
         left >= 0 && right < n && s[left] === s[right];
         left--, right++) {
      cuts[right + 1] = Math.min(cuts[right + 1], cuts[left] + 1);
    }

    // Even-length palindromes.
    for (let left = center, right = center + 1;
         left >= 0 && right < n && s[left] === s[right];
         left--, right++) {
      cuts[right + 1] = Math.min(cuts[right + 1], cuts[left] + 1);
    }
